CREATE TABLE `compliance_case_findings` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `evidence_id` text DEFAULT '' NOT NULL, `requirement_id` text DEFAULT '' NOT NULL, `finding_code` text NOT NULL, `severity` text NOT NULL CHECK ( `severity` IN ('information', 'minor', 'major', 'critical') ), `description` text NOT NULL, `status` text DEFAULT 'open' NOT NULL CHECK ( `status` IN ('open', 'resolved', 'waived') ), `raised_by_uid` text NOT NULL, `raised_at` text NOT NULL, `resolved_by_uid` text DEFAULT '' NOT NULL, `resolved_at` text DEFAULT '' NOT NULL, `resolution_note` text DEFAULT '' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE INDEX `compliance_case_findings_case_status_idx` ON `compliance_case_findings` (`case_id`, `status`, `severity`, `raised_at`);
CREATE INDEX `compliance_case_findings_org_status_idx` ON `compliance_case_findings` (`organisation_id`, `status`, `severity`, `raised_at`);
CREATE TABLE `compliance_case_decisions` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `case_revision` integer NOT NULL CHECK (`case_revision` > 0), `decision_type` text NOT NULL CHECK ( `decision_type` IN ( 'evidence_complete', 'eligibility', 'ready_to_submit', 'submission_outcome', 'case_closure' ) ), `outcome` text NOT NULL CHECK ( `outcome` IN ('approved', 'rejected', 'changes_required', 'withdrawn') ), `basis_snapshot` text NOT NULL CHECK (json_valid(`basis_snapshot`)), `primary_reviewer_uid` text NOT NULL, `secondary_reviewer_uid` text DEFAULT '' NOT NULL, `decided_at` text NOT NULL, `created_at` text NOT NULL, CHECK ( `outcome` <> 'approved' OR `decision_type` NOT IN ('eligibility', 'ready_to_submit') OR ( `secondary_reviewer_uid` <> '' AND `secondary_reviewer_uid` <> `primary_reviewer_uid` ) ) );
CREATE INDEX `compliance_case_decisions_case_time_idx` ON `compliance_case_decisions` (`case_id`, `decided_at`, `id`);
CREATE INDEX `compliance_case_decisions_case_revision_idx` ON `compliance_case_decisions` (`case_id`, `case_revision`, `decision_type`, `decided_at`, `id`);
CREATE TABLE `compliance_decision_requests` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `case_revision` integer NOT NULL CHECK (`case_revision` > 0), `decision_type` text NOT NULL CHECK ( `decision_type` IN ('eligibility', 'ready_to_submit') ), `outcome` text NOT NULL CHECK (`outcome` = 'approved'), `basis_snapshot` text NOT NULL CHECK (json_valid(`basis_snapshot`)), `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ('pending', 'approved', 'rejected', 'withdrawn') ), `primary_reviewer_uid` text NOT NULL, `secondary_reviewer_uid` text DEFAULT '' NOT NULL, `reviewed_at` text DEFAULT '' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK ( (`status` = 'pending' AND `secondary_reviewer_uid` = '' AND `reviewed_at` = '') OR (`status` <> 'pending' AND `secondary_reviewer_uid` <> '' AND `secondary_reviewer_uid` <> `primary_reviewer_uid` AND `reviewed_at` <> '') ) );
CREATE INDEX `compliance_decision_requests_case_status_idx` ON `compliance_decision_requests` (`case_id`, `case_revision`, `status`, `created_at`, `id`);
CREATE INDEX `compliance_decision_requests_org_status_idx` ON `compliance_decision_requests` (`organisation_id`, `status`, `created_at`, `id`);
CREATE TABLE `compliance_equipment_records` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `record_type` text NOT NULL CHECK ( `record_type` IN ('installed', 'decommissioned', 'stock') ), `manufacturer` text DEFAULT '' NOT NULL, `model` text DEFAULT '' NOT NULL, `serial_number` text DEFAULT '' NOT NULL, `product_registry` text DEFAULT '' NOT NULL, `product_reference` text DEFAULT '' NOT NULL, `quantity` integer DEFAULT 1 NOT NULL CHECK (`quantity` > 0), `status` text NOT NULL CHECK ( `status` IN ( 'expected', 'received', 'installed', 'decommissioned', 'removed', 'returned', 'scrapped' ) ), `evidence_snapshot` text DEFAULT '{}' NOT NULL CHECK ( json_valid(`evidence_snapshot`) ), `recorded_by_uid` text NOT NULL, `recorded_at` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE INDEX `compliance_equipment_case_type_idx` ON `compliance_equipment_records` (`case_id`, `record_type`, `status`, `recorded_at`);
CREATE INDEX `compliance_equipment_serial_idx` ON `compliance_equipment_records` (`organisation_id`, `serial_number`, `status`);
CREATE TABLE `compliance_calculator_versions` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `activity_version_id` text NOT NULL, `calculator_key` text NOT NULL, `version` integer NOT NULL CHECK (`version` > 0), `title` text NOT NULL, `output_type` text NOT NULL CHECK ( `output_type` IN ( 'STC', 'VEEC', 'ESC', 'PRC', 'GJ', 'dollars', 'other' ) ), `specification` text NOT NULL CHECK (json_valid(`specification`)), `rounding_policy` text NOT NULL, `official_source_url` text NOT NULL, `official_source_version` text NOT NULL, `official_source_sha256` text NOT NULL CHECK ( length(`official_source_sha256`) = 64 AND lower(`official_source_sha256`) NOT GLOB '*[^0-9a-f]*' ), `approval_state` text DEFAULT 'draft' NOT NULL CHECK ( `approval_state` IN ( 'draft', 'testing', 'approved', 'blocked', 'withdrawn' ) ), `primary_approver_uid` text DEFAULT '' NOT NULL, `secondary_approver_uid` text DEFAULT '' NOT NULL, `approved_at` text DEFAULT '' NOT NULL, `withdrawn_at` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK ( `approval_state` <> 'approved' OR ( `primary_approver_uid` <> '' AND `secondary_approver_uid` <> '' AND `primary_approver_uid` <> `secondary_approver_uid` AND `approved_at` <> '' ) ) );
CREATE UNIQUE INDEX `compliance_calculator_versions_key_idx` ON `compliance_calculator_versions` (`activity_version_id`, `calculator_key`, `version`);
CREATE INDEX `compliance_calculator_versions_state_idx` ON `compliance_calculator_versions` (`organisation_id`, `approval_state`, `updated_at`);
CREATE TABLE `compliance_calculator_test_vectors` ( `id` text PRIMARY KEY NOT NULL, `calculator_version_id` text NOT NULL, `vector_key` text NOT NULL, `input_snapshot` text NOT NULL CHECK (json_valid(`input_snapshot`)), `expected_output` text NOT NULL CHECK (json_valid(`expected_output`)), `tolerance_snapshot` text DEFAULT '{}' NOT NULL CHECK ( json_valid(`tolerance_snapshot`) ), `source_citation` text NOT NULL, `last_result` text DEFAULT 'not_run' NOT NULL CHECK ( `last_result` IN ('not_run', 'passed', 'failed') ), `last_run_at` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_calculator_vectors_key_idx` ON `compliance_calculator_test_vectors` (`calculator_version_id`, `vector_key`);
CREATE TABLE `compliance_calculation_runs` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `case_revision` integer NOT NULL CHECK (`case_revision` > 0), `calculator_version_id` text NOT NULL, `input_snapshot` text NOT NULL CHECK (json_valid(`input_snapshot`)), `output_snapshot` text DEFAULT '{}' NOT NULL CHECK ( json_valid(`output_snapshot`) ), `status` text DEFAULT 'blocked' NOT NULL CHECK ( `status` IN ('blocked', 'calculated', 'verified', 'rejected') ), `blocked_reason` text DEFAULT '' NOT NULL, `run_by_uid` text NOT NULL, `run_at` text NOT NULL, `verified_by_uid` text DEFAULT '' NOT NULL, `verified_at` text DEFAULT '' NOT NULL, `created_at` text NOT NULL );
CREATE INDEX `compliance_calculation_runs_case_idx` ON `compliance_calculation_runs` (`case_id`, `case_revision`, `run_at`);
CREATE TABLE `compliance_submission_batches` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `program_id` text NOT NULL, `batch_number` text NOT NULL, `external_reference` text DEFAULT '' NOT NULL, `format` text NOT NULL CHECK (`format` IN ('json', 'csv', 'manual', 'api')), `status` text DEFAULT 'draft' NOT NULL CHECK ( `status` IN ( 'draft', 'ready', 'exported', 'submitted', 'partially_accepted', 'accepted', 'rejected', 'reconciled', 'cancelled' ) ), `payload_sha256` text DEFAULT '' NOT NULL CHECK ( `payload_sha256` = '' OR ( length(`payload_sha256`) = 64 AND lower(`payload_sha256`) NOT GLOB '*[^0-9a-f]*' ) ), `case_count` integer DEFAULT 0 NOT NULL CHECK (`case_count` >= 0), `certificate_quantity` integer DEFAULT 0 NOT NULL CHECK ( `certificate_quantity` >= 0 ), `created_by_uid` text NOT NULL, `exported_at` text DEFAULT '' NOT NULL, `submitted_at` text DEFAULT '' NOT NULL, `reconciled_at` text DEFAULT '' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_submission_batches_number_idx` ON `compliance_submission_batches` (`organisation_id`, `batch_number`);
CREATE INDEX `compliance_submission_batches_queue_idx` ON `compliance_submission_batches` (`organisation_id`, `status`, `created_at`);
CREATE TABLE `compliance_submission_batch_items` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `batch_id` text NOT NULL, `case_id` text NOT NULL, `case_revision` integer NOT NULL CHECK (`case_revision` > 0), `status` text DEFAULT 'staged' NOT NULL CHECK ( `status` IN ( 'staged', 'submitted', 'accepted', 'rejected', 'correction_required', 'removed' ) ), `external_reference` text DEFAULT '' NOT NULL, `result_snapshot` text DEFAULT '{}' NOT NULL CHECK ( json_valid(`result_snapshot`) ), `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_submission_batch_items_case_idx` ON `compliance_submission_batch_items` (`batch_id`, `case_id`);
CREATE INDEX `compliance_submission_batch_items_status_idx` ON `compliance_submission_batch_items` (`batch_id`, `status`, `created_at`);
CREATE TABLE `compliance_submission_artifacts` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `batch_id` text NOT NULL, `artifact_type` text NOT NULL CHECK ( `artifact_type` IN ( 'export_json', 'export_csv', 'submission_receipt', 'response_file', 'reconciliation_report' ) ), `object_key` text NOT NULL, `file_name` text NOT NULL, `content_type` text NOT NULL, `size_bytes` integer NOT NULL CHECK (`size_bytes` > 0), `sha256` text NOT NULL CHECK ( length(`sha256`) = 64 AND lower(`sha256`) NOT GLOB '*[^0-9a-f]*' ), `created_by_uid` text NOT NULL, `created_at` text NOT NULL );
CREATE INDEX `compliance_submission_artifacts_batch_idx` ON `compliance_submission_artifacts` (`batch_id`, `created_at`);
CREATE TABLE `compliance_submission_responses` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `batch_id` text NOT NULL, `batch_item_id` text DEFAULT '' NOT NULL, `response_type` text NOT NULL CHECK ( `response_type` IN ('accepted', 'rejected', 'warning', 'error', 'duplicate') ), `response_code` text DEFAULT '' NOT NULL, `message` text NOT NULL, `payload_snapshot` text DEFAULT '{}' NOT NULL CHECK ( json_valid(`payload_snapshot`) ), `occurred_at` text NOT NULL, `recorded_by_uid` text NOT NULL, `created_at` text NOT NULL );
CREATE INDEX `compliance_submission_responses_batch_idx` ON `compliance_submission_responses` (`batch_id`, `occurred_at`, `id`);
CREATE TABLE `compliance_certificate_lots` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `program_id` text NOT NULL, `batch_id` text DEFAULT '' NOT NULL, `certificate_type` text NOT NULL, `registry_lot_reference` text DEFAULT '' NOT NULL, `quantity` integer NOT NULL CHECK (`quantity` >= 0), `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ( 'pending', 'created', 'available', 'reserved', 'traded', 'retired', 'cancelled' ) ), `vintage_from` text DEFAULT '' NOT NULL, `vintage_to` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE INDEX `compliance_certificate_lots_inventory_idx` ON `compliance_certificate_lots` (`organisation_id`, `certificate_type`, `status`, `created_at`);
CREATE TABLE `compliance_trades` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `certificate_lot_id` text NOT NULL, `counterparty_reference` text NOT NULL, `quantity` integer NOT NULL CHECK (`quantity` > 0), `unit_price_cents` integer NOT NULL CHECK (`unit_price_cents` >= 0), `trade_date` text NOT NULL, `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ('pending', 'confirmed', 'settled', 'cancelled') ), `external_reference` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE INDEX `compliance_trades_status_idx` ON `compliance_trades` (`organisation_id`, `status`, `trade_date`);
CREATE TABLE `compliance_settlements` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `trade_id` text NOT NULL, `gross_cents` integer NOT NULL CHECK (`gross_cents` >= 0), `fee_cents` integer DEFAULT 0 NOT NULL CHECK (`fee_cents` >= 0), `net_cents` integer NOT NULL CHECK (`net_cents` >= 0), `due_date` text NOT NULL, `settled_at` text DEFAULT '' NOT NULL, `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ('pending', 'processing', 'settled', 'failed', 'cancelled') ), `external_reference` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK (`net_cents` = `gross_cents` - `fee_cents`) );
CREATE INDEX `compliance_settlements_status_idx` ON `compliance_settlements` (`organisation_id`, `status`, `due_date`);
CREATE UNIQUE INDEX `compliance_settlements_active_trade_idx` ON `compliance_settlements` (`trade_id`) WHERE `status` <> 'cancelled';
